                    for j in range(start,idx):
                        arr[codons[j][0]:codons[j][0]+3]=[True]*3
                start=idx+1
        if len(codons)-start>=mincod:
            for j in range(start,len(codons)):
                arr[codons[j][0]:codons[j][0]+3]=[True]*3
        maps[f]=arr
    return maps
