seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]
stops={'TAA','TAG','TGA'}
def up_run(s,i):  # codons ending just before position i (i is codon start of stop), frame same
    n=0
    while i-3>=0 and s[i-3:i] not in stops:
        n+=1;i-=3
    return n
def dn_run(s,i):
    n=0
    while i+3<=len(s) and s[i:i+3] not in stops:
        n+=1;i+=3
    return n
for nm,s in [('fwd',seq),('rev',rc)]:
    for f in range(3):
        for k in range((len(s)-f)//3):
            i=f+3*k
            if s[i:i+3] in stops:
                up=up_run(s,i)
                if up>=80:
                    # check shifted frames
                    for off,lab in [(-2,'-1shift'),(-1,'?'),(1,'+1shift?'),(2,'+2')]:
                        j=i+off
                        if j<0: continue
                        d=dn_run(s,j)
                        if d>=80:
                            print(nm,'frame',f,'stop',i,s[i:i+3],'upstream_framecodons',up,'| shifted start',j,lab,'downstream',d)
