def allorfs(s,mincod=20):
    out=[]
    for f in range(3):
        i=f
        codons=[]
        start=None
        for k in range((len(s)-f)//3):
            c=s[f+3*k:f+3*k+3]
            if c in stops:
                if start is not None and k-start>=mincod:
                    out.append((start*3+f,k*3+f,f))
                start=None
            else:
                if start is None: start=k
        if start is not None and ((len(s)-f)//3)-start>=mincod:
            out.append((start*3+f,((len(s)-f)//3)*3+f,f))
    return out
for nm,s in [('fwd',seq),('rev',rc)]:
    o=allorfs(s)
