def slippery_scan(s,f,label,a,b):
    print('---',label,'frame',f)
    for k in range((b-a)//3):
        i=a+3*k
        c1=s[i:i+3]; c2=s[i+3:i+6]
        if len(c1)<3 or len(c2)<3: continue
        # same or near-cognate: first two bases equal
        if c1[0]==c2[0] and c1[1]==c2[1] and c1 in ['AAA','AAG','AAT','AAC','TTT','TTC','TTA','TTG','GGG','GGA','GGC','CCC','CCA','CCG','CCT','CTT','CTC','GAA','GAG','TCC','TCT','AGA','AGG','GCT','GCC','GCA','GCG','TCA','TCG','ATT','ATC','ATA','GTT','GTC','GTA','CTG','CTA','TCT']:
            # require that the pair is a "repeat" like XXX+XXY (i.e. c1==c2 or differ in third base)
            if c1[:2]==c2[:2]:
                d=openlen(s,i+2)  # -1 shifted frame
                d0=openlen(s,i+6)
                if d>=40 or d0>=40:
                    print('  site at',i,c1,c2,' context',s[i-6:i+15],' -1frame_open',d,' 0frame_open',d0)
