import re
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]
stops={'TAA','TAG','TGA'}
def openlen(s,i,limit=1000):
    n=0
    while i+3<=len(s) and n<limit:
        if s[i:i+3] in stops: return n
        n+=1;i+=3
    return n
found=False
for nm,s in [('fwd',seq),('rev',rc)]:
    for m in re.finditer('ATG',s):
        i=m.start()
        L=openlen(s,i)
        if 5<=L<=70:
            end=i+3*L  # stop codon start
            if s[end:end+3] in stops:
                for off in range(0,11):
                    for f2 in range(3):
                        j=end+off+f2
                        L2=openlen(s,j)
                        if L2>=100:
                            print(nm,'small ORF at',i,'len',L,'stop at',end,'| shifted/long ORF at',j,'len',L2,'frame diff',(j-i)%3)
                            found=True
print('done', found)
"}

